"""Source-only AI transcription before first v9 prediction on either new project."""
import json,hashlib
from pathlib import Path
from itertools import combinations
from PIL import Image,ImageDraw
ROOT=Path(__file__).resolve().parents[2];sheets={}
def add(g,n,roi,nodes,edges,dashed=(),branch=(),ignore=()):
 p=ROOT/'.benchmark-data/v9-held'/g/f'p{n}-2400.png';im=Image.open(p).convert('RGB');w,h=im.size;ox,oy=roi[:2];norm=lambda b:[v/[w,h][k%2] for k,v in enumerate(b)];nn=[{'id':k,'kind':kind,'bbox':norm([b[0]+ox,b[1]+oy,b[2]+ox,b[3]+oy])} for k,kind,b in nodes];es=sorted({tuple(sorted(e)) for e in edges});ids={p['id'] for p in nn};assert all(set(e)<=ids for e in es)
 s={'project':g,'group':g,'id':f'p{n}','role':'unseen-project-test','canvas':[w,h],'roi':norm(roi),'ignore':[norm([b[0]+ox,b[1]+oy,b[2]+ox,b[3]+oy]) for b in ignore],'nodes':nn,'edges':es,'edge_subsets':{'dashed':sorted(tuple(sorted(e)) for e in dashed),'branch':sorted(tuple(sorted(e)) for e in branch)},'image_sha256':hashlib.sha256(p.read_bytes()).hexdigest()};sheets[f'{g}-p{n}']=s;d=ImageDraw.Draw(im)
 for k,kind,b in nodes:b=[b[0]+ox,b[1]+oy,b[2]+ox,b[3]+oy];d.rectangle(b,outline='red',width=1);d.text((b[0],b[1]-11),k,fill='red')
 for b in ignore:d.rectangle((b[0]+ox,b[1]+oy,b[2]+ox,b[3]+oy),outline='blue')
 im.crop(roi).resize(((roi[2]-roi[0])*2,(roi[3]-roi[1])*2)).save(f'/tmp/v9-gt-{g}-{n}.png')
 # Class-agnostic boxes and physical image adjacency; type is source aid only.
clique=lambda *ids:list(combinations(ids,2))
